<?php $uiText=\App\Core\ConsoleLocale::messages(); $interfaceLanguage=\App\Core\ConsoleLocale::resolve($_COOKIE[\App\Core\ConsoleLocale::COOKIE]??null); $e = static fn(mixed $v): string => htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); ?>
