<html lang="<?= $interfaceLanguage ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="alternate icon" href="/favicon.ico"><link rel="stylesheet" href="/theme/sensecms-admin.css"><link rel="stylesheet" href="/theme/sensecms-controls.css"><link rel="stylesheet" href="/theme/sensecms-login.css?v=20260826-brand"><link rel="stylesheet" href="/theme/sensecms-accessibility.css?v=20260831-wcag-1"><link rel="stylesheet" href="/theme/sensecms-text-zoom.css?v=20260831-wcag-1"><title><?= $e($uiText('Sign in · SenseCMS')) ?></title><?php require __DIR__.'/interface-language-script.php'; ?></head>
