) ?></div><?php endif; ?><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><button type="submit" class="btn bg-primary text-white sensecms-login-submit"><?= $e($uiText('Sign in')) ?></button><div class="sensecms-login-footer"><a href="<?= $e($sensecmsUrl) ?>" target="_blank" rel="noopener"><?= $e($uiText('Powered by SenseCMS')) ?></a><div class="sensecms-login-languages" role="group" aria-label="<?= $e($uiText('Interface language')) ?>"><?php foreach (['en'=>'English','pl'=>'Polski'] as $code=>$name): ?><button type="button" lang="<?= $code ?>" data-login-language="<?= $code ?>" aria-pressed="<?= $code===$interfaceLanguage?'true':'false' ?>"><?= $name ?></button><?php endforeach; ?></div></div></form></section></main>
